#include <stdio.h>
int main(void){
    int n=4;
    int adj[4][4]={0};
    int e[][2]={{0,1},{1,2},{2,3},{3,0}};  /* 偶环 => 二分 */
    int m=4;
    for(int k=0;k<m;k++){ adj[e[k][0]][e[k][1]]=1; adj[e[k][1]][e[k][0]]=1; }
    int color[4]; for(int i=0;i<n;i++) color[i]=-1;
    int q[4],head=0,tail=0; color[0]=0; q[tail++]=0; int bip=1;
    while(head<tail){
        int u=q[head++];
        for(int v=0;v<n;v++) if(adj[u][v]){
            if(color[v]<0){ color[v]=color[u]^1; q[tail++]=v; }
            else if(color[v]==color[u]){ bip=0; }
        }
    }
    printf("bipartite: %s\n", bip ? "yes" : "no");
    return 0;
}
